// ─── File: RetainedHeapDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.retained;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RetainedHeapDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // A SINGLE cache object. Its SHALLOW size is tiny (a few fields).
        ScoringCache cache = new ScoringCache();

        // Feed it many records. The cache RETAINS all of them (unbounded map).
        int count = 500_000;
        for (int i = 0; i < count; i++) {
            cache.score("TXN-" + i, 256); // each record carries a 256-byte payload
        }

        // Approximate SHALLOW vs RETAINED for teaching (real tools compute exactly).
        long cacheShallowBytes = ScoringCache.SHALLOW_BYTES;        // the cache object itself
        long perRecordShallow = TransactionRecord.shallowBytes(256);
        long retainedBytes = cacheShallowBytes
                + (long) cache.size() * (perRecordShallow + 48 /* map Node+key */);

        log.info(() -> "cache SHALLOW heap ≈ " + cacheShallowBytes + " bytes (tiny!)");
        log.info(() -> "cache RETAINED heap ≈ " + (retainedBytes / (1024 * 1024)) + " MB"
                + " (" + cache.size() + " records held alive)");
        log.warning(() -> "Sort a heap dump by RETAINED heap → this tiny cache is the top accumulator");
        log.info(() -> "Fix: bound the cache (LRU/size/TTL) so retained heap stays small");
    }
}

// ─── Would be in TransactionRecord.java (small shallow, MANY instances) ───
class TransactionRecord {
    private final String id;      // reference (4-8 bytes) + the String elsewhere
    private final byte[] payload; // the bulk of this record's shallow size
    TransactionRecord(String id, int payloadSize) {
        this.id = id; this.payload = new byte[payloadSize];
    }
    // Teaching helper: approximate shallow size = header + fields + payload array.
    static long shallowBytes(int payloadSize) {
        return 16 /* header */ + 8 /* two refs */ + 16 + payloadSize /* byte[] */;
    }
    String getId() { return id; }
}

// ─── Would be in ScoringCache.java (THE RETAINER — small object, huge retained set) ───
class ScoringCache {
    static final long SHALLOW_BYTES = 24; // header + a map reference field: tiny
    // Unbounded map: this single object retains EVERY record ever scored.
    private final java.util.Map<String, TransactionRecord> cache = new java.util.HashMap<>();
    void score(String txnId, int payloadSize) {
        cache.put(txnId, new TransactionRecord(txnId, payloadSize)); // never evicts → leak
    }
    int size() { return cache.size(); }
}
